import std.io
import std.string

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let a = string.parseInt("9223372036854775807")
    match a {
        Some(v) => { io.println("got ${v}") }
        None => { io.println("got-none") }
    }
    let b = string.parseUInt("9223372036854775807")
    match b {
        Some(v) => { io.println("fits ${v}") }
        None => { io.println("fits-none") }
    }
    return Ok(())
}
